<script setup lang="ts">definePageMeta({layout:"admin",middleware:"admin"});const{data,refresh}=await useFetch("/api/admin/announcements");const form=reactive({label:"",message:"",href:null as string|null,active:true,sortOrder:0,startsAt:null,endsAt:null});async function create(){await $fetch("/api/admin/announcements",{method:"POST",body:form});form.label="";form.message="";await refresh();}async function remove(id:string){if(confirm("Hapus announcement?")){await $fetch(`/api/admin/announcements/${id}`,{method:"DELETE"});await refresh();}}async function toggle(item:any){await $fetch(`/api/admin/announcements/${item.id}`,{method:"PATCH",body:{label:item.label,message:item.message,href:item.href,active:!item.active,sortOrder:item.sort_order,startsAt:item.starts_at,endsAt:item.ends_at}});await refresh();}useSeoMeta({title:"Admin Content"});</script>
<template><div><AdminPageHeader title="Header billboard" description="Announcement aktif ditampilkan bergantian pada storefront."/><div class="grid gap-6 xl:grid-cols-[400px_1fr]"><form class="surface grid gap-4 p-5" @submit.prevent="create"><label class="field-label">Label<input v-model="form.label" class="field" required></label><label class="field-label">Pesan<input v-model="form.message" class="field" required></label><label class="field-label">Link<input v-model="form.href" class="field"></label><label class="field-label">Urutan<input v-model.number="form.sortOrder" type="number" class="field"></label><label class="flex gap-2 text-sm font-bold"><input v-model="form.active" type="checkbox">Aktif</label><AppButton type="submit">Tambah announcement</AppButton></form><div class="grid gap-3"><article v-for="item in data?.announcements" :key="(item as any).id" class="surface flex items-center justify-between gap-5 p-5"><div><p class="eyebrow">{{(item as any).label}}</p><p class="mt-1 font-bold">{{(item as any).message}}</p><small>{{(item as any).active?'Aktif':'Nonaktif'}}</small></div><div class="flex gap-2"><AppButton variant="secondary" @click="toggle(item)">Toggle</AppButton><AppButton variant="danger" @click="remove((item as any).id)">Hapus</AppButton></div></article></div></div></div></template>
